const draftEvidence = (id: string, label: string, url: string, type: Evidence["type"] = "PAPER"): Evidence => ({ id, type, verificationLevel: "REPORTED", label, sourceUrl: url });
const draftClaim = (id: string, specId: string, relation: Claim["relation"], value: string, claimType: Claim["claimType"], author: string, year: number, source: string, evidenceId: string, basis: NonNullable<Claim["evidenceBasis"]>[number] = "THEORETICAL_DERIVATION"): Claim => ({ id, specificationVersionId: specId, relation, value: { kind: "text", value }, claimType, status: "DRAFT", epistemicStatus: "LITERATURE_ASSERTED", scientificStatus: "ACCEPTED", registryReviewStatus: "UNREVIEWED", evidenceBasis: [basis], evidenceIds: [evidenceId], author, year, source });
const readyDraft = (id: string, title: string, category: string, direction: Direction, description: string, formalQuestion: string, constraints: Record<string, string>, claim: [Claim["relation"], string, Claim["claimType"], string, number, string], url: string, basis: NonNullable<Claim["evidenceBasis"]>[number] = "THEORETICAL_DERIVATION"): ResearchPacket => { const spec = draftSpec(`SP-${id}-V1`, id, formalQuestion, constraints); const evidence = draftEvidence(`EVD-${id}-1`, title, url, basis === "OBSERVATION" ? "OBSERVATION" : basis === "CONSTRUCTION" ? "CONSTRUCTION" : "PAPER"); return { limit: { id, title, category, status: "DRAFT", direction, summary: description, limitKind: basis === "OBSERVATION" ? "OBSERVED_RECORD" : "THEORETICAL_BOUND" }, specification: spec, claims: [draftClaim(`CLM-${id}-1`, spec.id, claim[0], claim[1], claim[2], claim[3], claim[4], claim[5], evidence.id, basis)], evidence: [evidence], registryReviewStatus: "UNREVIEWED", publicationState: "DRAFT", ingestionReadiness: "READY_FOR_EDITORIAL_REVIEW", independentRegistryReviews: 0 }; };

export const researchedDraftPackets: ResearchPacket[] = [
  readyDraft("LR-DRAFT-CARNOT", "Carnot heat-engine efficiency", "Physics / Thermodynamics", "MAXIMIZE", "No heat engine operating between two temperature reservoirs can convert heat to work more efficiently than a reversible one: the Carnot limit η ≤ 1 − T_c/T_h, where T_h and T_c are the hot and cold reservoir temperatures.", "What is the maximum thermodynamic efficiency η achievable by any heat engine operating between a hot reservoir at T_h and a cold reservoir at T_c?", { hotReservoir: "T_h", coldReservoir: "T_c", process: "reversible" }, ["<=", "1 − T_c/T_h", "UPPER_BOUND", "Sadi Carnot", 1824, "Réflexions sur la puissance motrice du feu"], "https://openstax.org/books/college-physics/pages/15-4-carnots-perfect-heat-engine-the-second-law-of-thermodynamics-restated"),
  readyDraft("LR-DRAFT-LANDAUER", "Landauer bit-erasure limit", "Physics / Information", "MINIMIZE", "Erasing one bit of information in a logically irreversible way necessarily dissipates heat into the environment — a fundamental link between information and thermodynamics. The minimum dissipated energy is Q ≥ k_B T ln(2), where T is the system's temperature.", "What is the minimum energy Q that must be dissipated as heat to logically erase one bit of information at temperature T?", { temperature: "T", operation: "logically irreversible bit erasure" }, [">=", "k_B T ln(2)", "LOWER_BOUND", "Rolf Landauer", 1961, "Irreversibility and Heat Generation in the Computing Process"], "https://doi.org/10.1147/RD.53.0183"),
  readyDraft("LR-DRAFT-BEKENSTEIN", "Bekenstein entropy bound", "Physics / Gravitation", "MAXIMIZE", "The entropy — and so the total information content — of any physical system is capped by its energy and physical size: S ≤ 2π k_B E R/(ℏ c) for a system with energy E confined within radius R, setting an absolute upper limit on how much information can fit in a bounded region of space.", "What is the maximum entropy S — and so the maximum information content — of a physical system with energy E confined within a sphere of radius R?", { system: "bounded physical system", energy: "E", radius: "R" }, ["<=", "2π k_B E R/(ℏ c)", "UPPER_BOUND", "Jacob Bekenstein", 1981, "Universal upper bound on the entropy-to-energy ratio for bounded systems"], "https://journals.aps.org/prd/abstract/10.1103/PhysRevD.23.287"),
  readyDraft("LR-DRAFT-ML", "Margolus–Levitin quantum speed limit", "Physics / Quantum", "MINIMIZE", "The Margolus–Levitin theorem sets a fundamental speed limit on how fast any physical process, including computation, can occur: an isolated quantum system needs at least τ ≥ πℏ/[2(E−E₀)] to evolve into a fully distinguishable (orthogonal) state.", "What is the minimum time τ for an isolated quantum system with mean energy E above its ground state E₀ to evolve into an orthogonal state?", { system: "isolated quantum system", energy: "mean energy above ground E−E₀" }, [">=", "πℏ/[2(E−E₀)]", "LOWER_BOUND", "Norman Margolus and Lev Levitin", 1998, "The maximum speed of dynamical evolution"], "https://www.sciencedirect.com/science/article/pii/S0167278998000542"),
  readyDraft("LR-DRAFT-SHANNON", "Shannon channel capacity and source-coding limits", "Information Theory", "MAXIMIZE", "Shannon's noisy-channel coding theorem defines the hard ceiling on reliable communication: no coding scheme can transmit information faster than a channel's capacity without introducing errors, no matter how sophisticated the encoding.", "What is the maximum rate C at which information can be transmitted over a channel with bandwidth B and signal-to-noise ratio P/N with arbitrarily low error probability?", { channel: "specified probabilistic channel", noise: "specified", reliability: "vanishing error" }, ["<=", "B log₂(1 + P/N)", "UPPER_BOUND", "Claude Shannon", 1948, "A Mathematical Theory of Communication"], "https://onlinelibrary.wiley.com/doi/pdf/10.1002/j.1538-7305.1948.tb00917.x"),
  readyDraft("LR-DRAFT-NYQUIST", "Nyquist sampling limit", "Signal Processing", "MAXIMIZE", "The Nyquist–Shannon sampling theorem sets the minimum rate at which a continuous signal must be sampled to be perfectly reconstructed — sample too slowly and distinct frequencies become indistinguishable (aliasing).", "What is the minimum sampling rate needed to perfectly reconstruct a signal band-limited to bandwidth B?", { signal: "band-limited", bandwidth: "B", reconstruction: "ideal" }, [">=", "2B samples/second", "LOWER_BOUND", "Harry Nyquist", 1928, "Certain Topics in Telegraph Transmission Theory"], "https://doi.org/10.1109/T-AIEE.1928.5055024"),
  readyDraft("LR-DRAFT-HOLEVO", "Holevo accessible-information bound", "Quantum Information", "MAXIMIZE", "No measurement strategy, however clever, can extract more classical (readable) information out of a quantum ensemble than its Holevo quantity χ — a hard ceiling on quantum communication capacity that sits below the naive per-qubit rate one might expect.", "What is the maximum amount of classical information χ that any measurement can extract from a quantum ensemble?", { ensemble: "quantum ensemble", measurement: "arbitrary POVM" }, ["<=", "χ(ensemble)", "UPPER_BOUND", "Alexander Holevo", 1973, "Bounds for the Quantity of Information Transmitted by a Quantum Communication Channel"], "https://www.mathnet.ru/eng/ppi/v9/i3/p3"),
  readyDraft("LR-DRAFT-NO-CLONING", "Perfect cloning of an arbitrary unknown quantum state", "Quantum Information", "MAXIMIZE", "The no-cloning theorem is one of quantum mechanics' foundational impossibility results: unlike classical information, an arbitrary unknown quantum state cannot be copied — a direct consequence of the linearity of quantum evolution, and the basis for quantum cryptography's security guarantees.", "Does there exist a physical process that perfectly copies an arbitrary unknown quantum state onto a second system?", { state: "arbitrary unknown quantum state", clone: "perfect universal" }, ["=", "impossible", "COUNTEREXAMPLE", "Wootters and Zurek", 1982, "A single quantum cannot be cloned"], "https://www.nature.com/articles/299802a0", "MATHEMATICAL_PROOF"),
  readyDraft("LR-DRAFT-RAMSEY33", "Ramsey number R(3,3)", "Mathematics / Combinatorics", "MINIMIZE", "Ramsey's theorem guarantees that large enough structures always contain order: however you two-color the edges of a large enough complete graph, a monochromatic triangle becomes unavoidable. R(3,3) is the smallest such threshold.", "What is the least n such that every two-coloring of the edges of the complete graph K_n contains a monochromatic triangle?", { graph: "complete graph K_n", colors: "2" }, ["=", "6", "EXACT_VALUE", "Frank Ramsey", 1930, "On a Problem of Formal Logic"], "https://encyclopediaofmath.org/wiki/Ramsey_number", "MATHEMATICAL_PROOF"),
  readyDraft("LR-DRAFT-KISSING4", "Kissing number in four dimensions", "Mathematics / Geometry", "MAXIMIZE", "The kissing number problem asks how many equal, non-overlapping spheres can simultaneously touch a central sphere of the same size — a question that gets dramatically harder as dimension increases, and is only exactly solved in a handful of dimensions.", "What is the maximum number of non-overlapping unit spheres that can simultaneously touch a central unit sphere in four-dimensional Euclidean space?", { dimension: "4", objects: "equal Euclidean spheres" }, ["=", "24", "EXACT_VALUE", "Oleg Musin", 2008, "The kissing number in four dimensions"], "https://geodesic.mathdoc.fr/articles/10.4007/annals.2008.168.1/", "MATHEMATICAL_PROOF"),
  readyDraft("LR-DRAFT-E8", "Optimal sphere packing in eight dimensions", "Mathematics / Geometry", "MAXIMIZE", "The sphere packing problem asks what fraction of space can be filled by non-overlapping equal spheres. In eight dimensions, the extraordinarily symmetric E8 lattice achieves the provably optimal arrangement — a landmark 2016 result.", "What is the maximum density achievable by any packing of non-overlapping equal spheres in eight-dimensional Euclidean space?", { dimension: "8", packing: "equal spheres" }, ["=", "E8 packing optimum", "EXACT_VALUE", "Maryna Viazovska", 2017, "The sphere packing problem in dimension 8"], "https://annals.math.princeton.edu/2017/185-3/p07", "MATHEMATICAL_PROOF"),
  readyDraft("LR-DRAFT-TSP", "Metric TSP approximation frontier", "Algorithms / Approximation", "MINIMIZE", "The traveling salesman problem — finding the shortest route visiting every city once — is NP-hard to solve exactly, so research focuses on how close a fast algorithm can guarantee to get to the true optimum for realistic (metric) instances.", "What is the best approximation ratio achievable in polynomial time for metric traveling salesman, assuming P ≠ NP?", { problem: "metric TSP", assumption: "P ≠ NP for hardness claim" }, ["<=", "3/2 − ε", "UPPER_BOUND", "Karlin, Klein, Oveis Gharan", 2022, "A (slightly) improved approximation algorithm for metric TSP"], "https://pubsonline.informs.org/doi/10.1287/opre.2022.2338", "COMPUTATIONAL_PROOF"),
  (() => { const packet = readyDraft("LR-DRAFT-OMEGA", "Matrix-multiplication exponent", "Algorithms / Complexity", "MINIMIZE", "Matrix multiplication underlies everything from computer graphics to machine learning. The naive algorithm takes O(n³) operations for n×n matrices, but faster algorithms exist — the matrix multiplication exponent ω tracks the best asymptotic speed anyone has proven achievable.", "The exponent ω is the infimum such that n×n matrix multiplication uses O(n^ω) arithmetic operations.", { model: "arithmetic complexity", matrices: "n×n" }, [">=", "2", "LOWER_BOUND", "Williams, Xu, Xu, Zhou", 2025, "New bounds for matrix multiplication"], "https://epubs.siam.org/doi/pdf/10.1137/1.9781611978322.63", "COMPUTATIONAL_PROOF"); packet.claims.push({ ...packet.claims[0], id: "CLM-LR-DRAFT-OMEGA-2", relation: "<", value: { kind: "text", value: "2.371339" }, claimType: "UPPER_BOUND", methodSummary: "Best published upper bound on the matrix-multiplication exponent." }); return packet; })(),
  readyDraft("LR-DRAFT-C", "Speed of light in vacuum", "Physics / Fundamental Constants", "MAXIMIZE", "The speed of light in vacuum is one of the few physical constants whose value is exact by definition rather than measurement — the 1983 SI redefinition of the metre fixed it precisely, making it the ultimate speed limit for information and matter in relativity.", "What is the SI-defined value of c, the speed of light in vacuum?", { system: "SI", medium: "vacuum" }, ["=", "299792458 m/s", "EXACT_VALUE", "BIPM / SI", 1983, "SI definition of the metre"], "https://physics.nist.gov/cuu/Constants/Value/c.html", "FORMAL_PROOF"),
  readyDraft("LR-DRAFT-GENOME", "Smallest demonstrated autonomously growing bacterial cell", "Biology / Synthetic Biology", "MINIMIZE", "How few genes does a living cell need to independently grow and divide? The JCVI-syn3.0 synthetic bacterium demonstrates the smallest genome shown to support autonomous life in a laboratory setting — not a claim about the theoretical minimum for life itself.", "What is the smallest genome demonstrated to support a viable, independently growing bacterial cell?", { organism: "JCVI-syn3.0", metric: "protein-coding and essential genes", scope: "demonstrated cell, not minimum for life" }, ["<=", "473 genes / 531560 bp", "CONSTRUCTION", "Hutchison et al.", 2016, "Design and synthesis of a minimal bacterial genome"], "https://jcvi.com/media-center/first-minimal-synthetic-bacterial-cell-designed-and-constructed-scientists-venter", "CONSTRUCTION"),
  readyDraft("LR-DRAFT-C3", "C3 photosynthetic efficiency", "Biology / Photosynthesis", "MAXIMIZE", "Photosynthesis converts sunlight into chemical energy, but real-world efficiency falls far short of the theoretical maximum due to biochemical and physical losses. This record cites the observed efficiency ceiling for C3 plants — the majority of crop species — under a specific modeled canopy scenario.", "What is the observed canopy-level photosynthetic efficiency for C3 plants under the Zhu–Long–Ort frozen-conditions model?", { pathway: "C3", conditions: "frozen Zhu–Long–Ort model" }, ["=", "4.6%", "EXACT_VALUE", "Zhu, Long, Ort", 2010, "Improving photosynthetic efficiency for greater yield"], "https://pubmed.ncbi.nlm.nih.gov/18374559/", "OBSERVATION"),
  readyDraft("LR-DRAFT-HAYFLICK", "Historical Hayflick fibroblast record", "Biology / Cell Aging", "MAXIMIZE", "Normal human cells don't divide forever — the Hayflick limit is the historical observation that established cellular senescence as a real biological phenomenon, not the discovery of a single universal number.", "How many population doublings were observed before senescence in Hayflick and Moorhead's studied human diploid fibroblast strains?", { cell: "human diploid fibroblast strains", metric: "subcultivations", scope: "historical observation" }, ["=", "about 50 subcultivations", "CONSTRUCTION", "Hayflick and Moorhead", 1961, "The serial cultivation of human diploid cell strains"], "https://pubmed.ncbi.nlm.nih.gov/13905658/", "OBSERVATION"),
  readyDraft("LR-DRAFT-DNA", "DNA information density", "Data Storage / Molecular", "MAXIMIZE", "DNA can in principle store far more information per gram than any other known medium. This tracks two genuinely different figures that should never be conflated: the theoretical raw nucleotide encoding limit, and the density actually demonstrated by real error-corrected schemes like DNA Fountain — which are orders of magnitude apart.", "What is the theoretical raw information density achievable by DNA-based storage, versus the density actually demonstrated by a real error-corrected encoding scheme?", { medium: "DNA", metrics: "raw theoretical versus demonstrated coded density" }, ["<=", "455 EB/g theoretical; 215 PB/g demonstrated", "UPPER_BOUND", "Erlich and Zielinski", 2017, "DNA Fountain enables a robust and efficient storage architecture"], "https://www.science.org/doi/10.1126/science.aaj2038"),
  readyDraft("LR-DRAFT-GRAPHENE", "Graphene intrinsic strength", "Materials Science", "MAXIMIZE", "Graphene is the strongest material ever measured. This record cites the specific tensile strength observed for defect-free monolayer graphene under controlled nanoindentation testing — a scoped experimental result, not a claim about bulk graphene sheets or composites.", "What tensile strength was measured for defect-free monolayer graphene under controlled nanoindentation testing?", { material: "graphene", metric: "tensile strength", scope: "cited experiment" }, ["=", "130 GPa", "EXACT_VALUE", "Lee et al.", 2008, "Measurement of the elastic properties and intrinsic strength of monolayer graphene"], "https://pubmed.ncbi.nlm.nih.gov/18635798/", "OBSERVATION"),
  readyDraft("LR-DRAFT-OPTICAL", "Optical-fiber capacity-distance demonstration", "Networking / Optical", "MAXIMIZE", "Optical fiber capacity-distance demonstrations track the practical frontier of how much data can be transmitted how far through fiber — a moving target as multi-core fiber and better amplification push the record higher each year.", "What is the highest verified data rate demonstrated over the longest distance in a single optical fiber transmission experiment?", { fiber: "19-core standard cladding", distance: "1808 km", metric: "capacity-distance" }, ["=", "1.02 Pb/s over 1808 km", "CONSTRUCTION", "NICT", 2025, "Ultra-high capacity optical fiber transmission"], "https://www.nict.go.jp/en/press/2025/05/29-1.html", "OBSERVATION"),
  readyDraft("LR-DRAFT-COVERING", "Thinnest covering of the plane by congruent circles", "Mathematics / Geometry", "MINIMIZE", "Covering the plane with congruent circles and leaving no gaps forces the circles to overlap. The thinnest such covering — the arrangement with the least overlap, achieved by centering circles on a hexagonal lattice — has density 2π/√27 ≈ 1.209, meaning the circles' total area exceeds the plane's area by about 21%.", "What is the minimum-density arrangement of congruent circles that covers the entire Euclidean plane with no gaps?", { objects: "congruent circles", domain: "Euclidean plane" }, ["=", "2π/√27", "EXACT_VALUE", "László Fejes Tóth", 1940, "Regular circle coverings"], "https://www.jstor.org/stable/i340747", "MATHEMATICAL_PROOF"),
  readyDraft("LR-DRAFT-NEUTRON", "Rhoades–Ruffini neutron-star mass bound", "Astrophysics", "MAXIMIZE", "Beyond a certain mass, a neutron star's own gravity overwhelms the quantum pressure holding it up, and it collapses into a black hole. The exact maximum mass depends on the poorly-constrained neutron-star equation of state; this record cites an early rigorous bound assuming causality.", "Under the causal equation-of-state assumption, what is the maximum possible mass of a stable neutron star?", { object: "neutron star", assumptions: "causal EOS and stated model" }, ["<=", "3.2 M☉", "UPPER_BOUND", "Rhoades and Ruffini", 1974, "Maximum mass of a neutron star"], "https://journals.aps.org/prl/abstract/10.1103/PhysRevLett.32.324"),
  readyDraft("LR-DRAFT-CHANDRA", "Historical Chandrasekhar white-dwarf mass calculation", "Astrophysics", "MAXIMIZE", "Before neutron stars were even confirmed to exist, Chandrasekhar showed that white dwarf stars have a maximum possible mass — beyond it, electron degeneracy pressure can no longer support the star against gravitational collapse. His original 1931 calculation used an idealized, composition-independent model.", "Under Chandrasekhar's 1931 idealized model, what is the maximum mass a white dwarf star can have before gravitational collapse?", { object: "ideal white dwarf", scope: "Chandrasekhar 1931 historical model" }, ["=", "0.91 M☉", "EXACT_VALUE", "Subrahmanyan Chandrasekhar", 1931, "The maximum mass of ideal white dwarfs"], "https://repository.ias.ac.in/70320/", "THEORETICAL_DERIVATION"),
];

