export const aiChinchillaScalingResearchPacket = readyDraft("LR-DRAFT-CHINCHILLA", "Compute-optimal language-model scaling", "AI / Scaling Laws", "MINIMIZE", "Training a fixed compute budget into an ever-larger model isn't always the best use of that compute — the Chinchilla study found that model size and training-token count should scale together, not model size alone, to reach the best loss for a given budget.", "Under a fixed compute budget, what is the jointly compute-optimal model size and training-token count for a specified autoregressive language-model family and data regime?", { objective: "next-token loss", compute: "fixed training FLOPs", variables: "parameter count and training tokens", regime: "specified model/data family" }, ["=", "N and D scale approximately together under the specified compute budget", "ASYMPTOTIC_BOUND", "Hoffmann et al.", 2022, "Training Compute-Optimal Large Language Models"], "https://arxiv.org/abs/2203.15556");
export const aiAttentionMemoryResearchPacket = readyDraft("LR-DRAFT-ATTENTION", "Transformer attention memory and IO scaling", "AI / Systems", "MINIMIZE", "Exact self-attention naively materializes a score matrix that grows quadratically with sequence length, which is what limits how long a context transformer models can practically handle. IO-aware kernels like FlashAttention avoid materializing that full matrix, trading a fixed compute cost for dramatically less memory traffic.", "For sequence length n and hidden width d, what is the peak memory and data movement for exact attention, distinguishing quadratic score-matrix materialization from IO-aware kernels such as FlashAttention?", { operation: "exact self-attention", sequenceLength: "n", hiddenWidth: "d", implementation: "materialized or IO-aware kernel" }, ["<=", "O(n²) score interactions; reduced intermediate memory with IO-aware tiling", "ASYMPTOTIC_BOUND", "Dao et al.", 2022, "FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness"], "https://arxiv.org/abs/2205.14135", "COMPUTATIONAL_PROOF");
export const aiRetrievalFloorResearchPacket = readyDraft("LR-DRAFT-RETRIEVAL", "Context-window retrieval reliability floor", "AI / Information Retrieval", "MAXIMIZE", "Long-context language models don't retrieve information from anywhere in their context window with equal reliability — accuracy varies with where the relevant fact sits, how many distractors surround it, and which model and prompt are used, so no single model-independent floor can be asserted.", "For a fixed context length, distractor count, corpus, model, and prompt, what retrieval accuracy is actually achieved under a specified evaluation protocol?", { task: "long-context retrieval", metric: "specified retrieval accuracy", corpus: "fixed benchmark corpus", context: "fixed token window and distractors" }, [">=", "protocol-specific measured retrieval accuracy", "COMPUTATIONAL_BOUND", "Long-context evaluation literature", 2024, "Empirical retrieval frontier under a fixed evaluation protocol"], "https://arxiv.org/abs/2307.03172", "OBSERVATION");

